package lending

import (
	"encoding/json"
	"math/big"
	"os"
	"strings"
	"testing"

	"github.com/ethereum/go-ethereum/common"
)

// testdata/morpho_sdk.json is generated by testdata/morpho_sdk.mjs with the
// Morpho SDK (@morpho-org/morpho-sdk 5.13.0), the library the Oku web app
// builds Morpho transactions with. Every builder must match it byte for byte.
type sdkTx struct {
	To    string `json:"to"`
	Data  string `json:"data"`
	Value string `json:"value"`
}

func TestBuildersMatchMorphoSDK(t *testing.T) {
	raw, err := os.ReadFile("testdata/morpho_sdk.json")
	if err != nil {
		t.Fatal(err)
	}
	var gold map[string]json.RawMessage
	if err = json.Unmarshal(raw, &gold); err != nil {
		t.Fatal(err)
	}
	d, err := Morpho(8453)
	if err != nil {
		t.Fatal(err)
	}
	user := common.HexToAddress("0x1111111111111111111111111111111111111111")
	usdc := common.HexToAddress("0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913")
	mp := MarketParams{LoanToken: usdc, CollateralToken: common.HexToAddress("0x4200000000000000000000000000000000000006"), Oracle: common.HexToAddress("0x663BECd10daE6C4A3Dcd89F1d76c1174199639B9"), Irm: common.HexToAddress("0x46415998764C29aB2a25CbeA6254146D50D22687"), Lltv: big.NewInt(860000000000000000)}
	var id string
	if err = json.Unmarshal(gold["market_id"], &id); err != nil {
		t.Fatal(err)
	}
	if mp.ID().Hex() != id {
		t.Fatalf("market id %s, sdk %s", mp.ID().Hex(), id)
	}
	n := func(s string) *big.Int { v, _ := new(big.Int).SetString(s, 10); return v }
	one := n("1000000000000000000")
	cases := map[string]func() (Call, error){
		"vault_deposit": func() (Call, error) {
			return d.VaultDeposit(common.HexToAddress("0x050ce30b927da55177a4914ec73480238bad56f0"), usdc, big.NewInt(1_000_000), n("1000300000000000000000000000"), user)
		},
		"supply_collateral": func() (Call, error) { return d.SupplyCollateral(mp, one, user) },
		"supply_collateral_borrow": func() (Call, error) {
			return d.SupplyCollateralBorrow(mp, one, big.NewInt(1_000_000_000), n("999700000000000000000000"), user)
		},
		"borrow": func() (Call, error) { return d.Borrow(mp, big.NewInt(5_000_000), n("999700000000000000000000"), user) },
		"repay_assets": func() (Call, error) {
			return d.RepayOnly(mp, Repay{Transfer: big.NewInt(5_000_000), MaxSharePrice: n("1000300000000000000000000")}, user)
		},
		"repay_shares_withdraw": func() (Call, error) {
			return d.RepayWithdrawCollateral(mp, Repay{Shares: n("4800000000000"), Transfer: big.NewInt(5_100_000), MaxSharePrice: n("1000300000000000000000000")}, one, user)
		},
		"withdraw_collateral": func() (Call, error) { return d.WithdrawCollateral(mp, one, user) },
	}
	for name, build := range cases {
		t.Run(name, func(t *testing.T) {
			var want sdkTx
			if err := json.Unmarshal(gold[name], &want); err != nil {
				t.Fatal(err)
			}
			got, err := build()
			if err != nil {
				t.Fatal(err)
			}
			if !strings.EqualFold(got.To.Hex(), want.To) || got.Hex() != strings.ToLower(want.Data) || got.Value.String() != want.Value {
				t.Fatalf("to %s data %s\nsdk to %s data %s", got.To.Hex(), got.Hex(), want.To, want.Data)
			}
		})
	}
}

func TestShareMathBounds(t *testing.T) {
	m := MarketState{TotalBorrowAssets: big.NewInt(80_193_060_898), TotalBorrowShares: big.NewInt(76_841_344_434_110_329), LastUpdate: big.NewInt(1000)}
	min, err := MinBorrowSharePrice(big.NewInt(1_000_000), m, DefaultSlippage)
	if err != nil || min.Sign() <= 0 {
		t.Fatalf("min borrow share price %v %v", min, err)
	}
	max, err := MaxRepaySharePrice(big.NewInt(1_000_000), nil, m, DefaultSlippage)
	if err != nil || max.Cmp(min) <= 0 {
		t.Fatalf("repay bound %v must exceed borrow bound %v", max, min)
	}
	accrued := m.AccrueBorrow(big.NewInt(2_301_588_388), 1000+7200)
	if accrued.TotalBorrowAssets.Cmp(m.TotalBorrowAssets) <= 0 {
		t.Fatal("accrual must grow borrow assets")
	}
	if _, err = MaxDepositSharePrice(big.NewInt(1), big.NewInt(0), DefaultSlippage); err == nil {
		t.Fatal("zero shares must fail")
	}
}
